export const membershipPlans={annual:{name:'Yearly',price:29.99,period:'year',detail:'About $2.50/month · billed yearly'},weekly:{name:'Weekly',price:2.99,period:'week',detail:'$2.99 billed every week'}};
let selected='annual',dialog,previousFocus;
const closeIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg>';
function render(){dialog.innerHTML=`<div class="membership-paywall"><header class="membership-top"><span>Bible Scroll Plus</span><button data-member="close" aria-label="Close membership preview">${closeIcon}</button></header><div class="membership-scroll"><div class="membership-art" aria-hidden="true"><img class="membership-clouds" src="illustration-pack/cloud-bank.png" alt="" width="480" height="208"><img class="membership-book" src="illustration-pack/open-book.png" alt="" width="158" height="140"><img class="membership-flower" src="illustration-pack/cosmos.png" alt="" width="78" height="86"></div><h2 id="membership-title">A little deeper.<br><em>A little closer.</em></h2><p class="membership-sub">Make room for your faith,<br>in the middle of your real life.</p><ul class="membership-features"><li><img src="illustration-pack/seedling.png" alt="" width="28" height="32">Guided reading at your pace</li><li><img src="illustration-pack/lantern.png" alt="" width="28" height="32">Passage study & thoughtful reflections</li><li><img src="illustration-pack/bookmark.png" alt="" width="28" height="32">Keep meaningful verses close</li></ul><fieldset class="membership-plans"><legend>Choose your plan</legend>${Object.entries(membershipPlans).map(([id,p])=>`<label class="membership-plan ${selected===id?'chosen':''}"><input type="radio" name="membership-plan" value="${id}" ${selected===id?'checked':''}><span class="plan-choice-indicator"></span><span class="membership-plan-copy"><strong>${p.name}${id==='annual'?'<b>Best value</b>':''}</strong><small>${p.detail}</small></span><span class="membership-amount">$${p.price.toFixed(2)}<small>/${p.period}</small></span></label>`).join('')}</fieldset><p class="membership-renewal">$${membershipPlans[selected].price.toFixed(2)} billed ${selected==='annual'?'yearly':'weekly'}. Auto-renews until canceled.<br>Prices in USD. No free trial included.</p></div><footer class="membership-footer"><button class="membership-cta" data-member="preview">Continue with ${membershipPlans[selected].name.toLowerCase()}</button><button class="membership-free" data-member="close">Continue with free reading</button><p class="membership-demo">Demo only · No payment will be taken.</p><div class="membership-links"><button data-member="restore">Restore purchases</button><button data-member="terms">Terms</button><button data-member="privacy">Privacy</button></div><p class="membership-notice" role="status" aria-live="polite"></p></footer></div>`;}
export function showMembership(){if(!dialog){dialog=document.createElement('dialog');dialog.id='membership-dialog';dialog.setAttribute('aria-labelledby','membership-title');document.body.append(dialog);dialog.addEventListener('change',e=>{if(e.target.name==='membership-plan'){selected=e.target.value;render();dialog.querySelector('input:checked')?.focus()}});dialog.addEventListener('close',()=>previousFocus?.isConnected&&previousFocus.focus({preventScroll:true}));dialog.addEventListener('click',e=>{const action=e.target.closest('[data-member]')?.dataset.member;if(!action)return;if(action==='close'){dialog.close();return}if(action==='preview'){const p=membershipPlans[selected];dialog.innerHTML=`<div class="membership-confirm"><img src="illustration-pack/butterfly.png" alt="" width="110" height="90"><h2 id="membership-title">Your ${p.name.toLowerCase()} plan preview</h2><p>$${p.price.toFixed(2)} per ${p.period}.</p><p>This is a design demo. No purchase was made and no payment details were collected.</p><button class="membership-cta" data-member="close">Return to the app</button><button class="membership-free" data-member="plans">Back to plans</button></div>`;dialog.querySelector('button').focus();return}if(action==='plans'){render();return}const messages={restore:'No App Store connection in this demo. Restore purchases will be available in the native app.',terms:'Preview terms: the selected plan renews at its displayed rate until canceled. Live purchases would be managed in your Apple account settings. No agreement or charge is created here.',privacy:'This paywall preview collects no payment information and sends no purchase data. App preferences remain in this browser.'};dialog.querySelector('.membership-notice').textContent=messages[action]||'';});}previousFocus=document.activeElement;render();if(!dialog.open)dialog.showModal();dialog.querySelector('[data-member="close"]').focus();}
window.addEventListener('bible-paywall-preview',showMembership);
